import { AiMark } from './AiMark';

interface AIHintProps {
  label: string;
}

// UIUX §22 — "A small 'Generated by AI — edit anything' hint sets expectations." One small
// brass AI mark, shown once per screen, not a recurring motif.
export function AIHint({ label }: AIHintProps) {
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 'var(--sp-1)', color: 'var(--text-secondary)', fontSize: 'var(--fs-xs)' }}>
      <AiMark size={14} />
      {label}
    </span>
  );
}
